package pe.com.asistencia.employee.domain;
import jakarta.persistence.*; import pe.com.asistencia.security.domain.User; import java.time.*;
@Entity @Table(name="employees")
public class Employee {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(name="employee_code",nullable=false,unique=true,length=40) private String code; @Column(name="document_type",nullable=false) private String documentType; @Column(name="document_number",nullable=false) private String documentNumber; @Column(name="first_names",nullable=false) private String firstNames; @Column(name="last_names",nullable=false) private String lastNames; @Column(name="photo_url",length=1000) private String photoUrl; private String email; private String phone; @Column(name="hire_date",nullable=false) private LocalDate hireDate; @Column(name="termination_date") private LocalDate terminationDate; @Column(nullable=false) private boolean active=true; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt;
 protected Employee(){} public Employee(String code,String documentType,String documentNumber,String firstNames,String lastNames,String photoUrl,String email,String phone,LocalDate hireDate,User user){this.code=code.toUpperCase();this.documentType=documentType.toUpperCase();this.documentNumber=documentNumber;this.firstNames=firstNames;this.lastNames=lastNames;this.photoUrl=photoUrl;this.email=email;this.phone=phone;this.hireDate=hireDate;this.user=user;}
 public Long getId(){return id;} public User getUser(){return user;} public String getCode(){return code;} public String getDocumentType(){return documentType;} public String getDocumentNumber(){return documentNumber;} public String getFirstNames(){return firstNames;} public String getLastNames(){return lastNames;} public String getPhotoUrl(){return photoUrl;} public String getEmail(){return email;} public String getPhone(){return phone;} public LocalDate getHireDate(){return hireDate;} public LocalDate getTerminationDate(){return terminationDate;} public boolean isActive(){return active;} public Instant getCreatedAt(){return createdAt;}
 public void update(String firstNames,String lastNames,String photoUrl,String email,String phone,LocalDate terminationDate,boolean active){this.firstNames=firstNames;this.lastNames=lastNames;this.photoUrl=photoUrl;this.email=email;this.phone=phone;this.terminationDate=terminationDate;this.active=active;}
}
